const nerves = {
  '嗅神经': 'olfactory nerve', '视神经': 'optic nerve', '动眼神经': 'oculomotor nerve', '滑车神经': 'trochlear nerve',
  '三叉神经': 'trigeminal nerve', '展神经': 'abducens nerve', '面神经': 'facial nerve', '前庭蜗神经': 'vestibulocochlear nerve',
  '舌咽神经': 'glossopharyngeal nerve', '迷走神经': 'vagus nerve', '副神经': 'accessory nerve', '舌下神经': 'hypoglossal nerve',
};
for (const [zh, en] of Object.entries(nerves)) {
  claimsEn[`${zh}的全程走行、相邻结构和功能有逐神经解剖描述。`] = `Nerve-specific anatomy describes the complete course, neighboring structures, and function of the ${en}.`;
  claimsEn[`${zh}的部分症状可与神经血管压迫综合征有关。`] = `Some symptoms involving the ${en} may be associated with neurovascular compression syndromes.`;
}
for (const [prefix, count] of [['C', 8], ['T', 12], ['L', 5], ['S', 5], ['Co', 1]]) {
  for (let n = 1; n <= count; n++) {
    const segment = `${prefix}${n}`;
    claimsEn[`脊髓 ${segment} 属于神经节段序列，神经节段与同名椎骨并非同一位置。`] = `Spinal ${segment} belongs to the neurological segment series; neurological segments and same-named vertebrae do not occupy the same location.`;
    gapsEn[`尚未为 ${segment} 独立配置原始病灶队列；临床分类标准只提供系统框架。`] = `An independent primary lesion cohort has not been assigned to ${segment}; clinical classification standards provide a system-level framework only.`;
  }
}

export const evidenceLevelLabelsEn = {'region-specific': 'Region-related research', 'system-level': 'System or network evidence', textbook: 'Textbook background', unresolved: 'Evidence not yet established'};
const verificationScopeEn = 'Bibliographic metadata checked against official records. Associated abstracts and classic findings are used for teaching; a human full-text review has not been completed for every paper.';

/** Translate an individual claim, including atlas-methodology claims. */
export function localizeEvidenceItem(item, lang = 'zh') {
  if (!item || lang !== 'en') return item;
  return { ...item, claim: claimsEn[item.claim] ?? item.claim, scope: scopesEn[item.scope] ?? item.scope };
}

export function localizeEvidence(entry, structureId, lang = 'zh') {
  if (!entry || lang !== 'en') return entry;
  return {
    ...entry,
    ...Object.fromEntries(['anatomy', 'function', 'cognition', 'clinical'].map(field => [field, (entry[field] || []).map(item => localizeEvidenceItem(item, lang))])),
    gaps: (entry.gaps || []).map(gap => gapsEn[gap] ?? gap),
    verificationScope: verificationScopeEn,
  };
}

/** Untranslated strings are surfaced during checks rather than silently dropped. */
export function untranslatedEvidenceStrings(entries, atlasEntries = {}) {
  const missing = new Set();
  for (const entry of Object.values(entries)) {
    for (const field of ['anatomy', 'function', 'cognition', 'clinical']) for (const item of entry[field] || []) {
      if (!claimsEn[item.claim] && /[\u3400-\u9fff]/.test(item.claim)) missing.add(item.claim);
      if (!scopesEn[item.scope] && /[\u3400-\u9fff]/.test(item.scope)) missing.add(item.scope);
    }
    for (const gap of entry.gaps || []) if (!gapsEn[gap] && /[\u3400-\u9fff]/.test(gap)) missing.add(gap);
  }
  for (const items of Object.values(atlasEntries)) for (const item of items) {
    if (!claimsEn[item.claim] && /[\u3400-\u9fff]/.test(item.claim)) missing.add(item.claim);
    if (!scopesEn[item.scope] && /[\u3400-\u9fff]/.test(item.scope)) missing.add(item.scope);
  }
  return [...missing];
}
